    strategicAlerts = pgTable2("strategic_alerts", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      alertType: alertTypeEnum("alert_type").notNull(),
      severity: priorityEnum("severity").default("medium"),
      title: varchar("title", { length: 255 }).notNull(),
      description: text2("description").notNull(),
      aiConfidence: decimal("ai_confidence", { precision: 3, scale: 2 }),
      // 0.00 to 1.00
      dataSourcesUsed: jsonb("data_sources_used"),
      // Array of data sources that triggered this alert
      suggestedActions: jsonb("suggested_actions"),
      // AI-recommended next steps
      recommendedScenario: varchar("recommended_scenario", { length: 255 }),
      // Suggested scenario to run
      targetAudience: jsonb("target_audience"),
      // C-suite roles this affects
      status: varchar("status", { length: 50 }).default("active"),
      // active, acknowledged, dismissed, resolved
      acknowledgedBy: varchar("acknowledged_by").references(() => users.id),
      acknowledgedAt: timestamp2("acknowledged_at"),
      resolvedAt: timestamp2("resolved_at"),
      createdAt: timestamp2("created_at").defaultNow().notNull(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
    executiveInsights = pgTable2("executive_insights", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      insightType: insightTypeEnum("insight_type").notNull(),
      title: varchar("title", { length: 255 }).notNull(),
      summary: text2("summary").notNull(),
      // Executive summary
      detailedAnalysis: text2("detailed_analysis"),
      // In-depth AI analysis
      keyFindings: jsonb("key_findings"),
      // Structured bullet points
      confidenceScore: decimal("confidence_score", { precision: 3, scale: 2 }),
      dataPoints: jsonb("data_points"),
      // Supporting data and metrics
      implications: jsonb("implications"),
      // Business implications
      recommendedActions: jsonb("recommended_actions"),
      // Actionable next steps
      timeHorizon: varchar("time_horizon", { length: 50 }),
      // immediate, short-term, long-term
      relatedScenarios: jsonb("related_scenarios"),
      // Array of scenario IDs
      boardReady: boolean("board_ready").default(false),
      // Flagged for board presentation
      viewedBy: jsonb("viewed_by"),
      // Track C-suite engagement
      createdAt: timestamp2("created_at").defaultNow().notNull(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
    actionHooks = pgTable2("action_hooks", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      name: varchar("name", { length: 255 }).notNull(),
      description: text2("description"),
      triggerEvent: varchar("trigger_event", { length: 100 }).notNull(),
      // decision_made, scenario_activated, etc.
      targetSystem: varchar("target_system", { length: 100 }).notNull(),
      // jira, slack, asana, netsuite
      actionType: varchar("action_type", { length: 100 }).notNull(),
      // create_project, send_notification, allocate_budget
      configuration: jsonb("configuration").notNull(),
      // System-specific settings
      mappingRules: jsonb("mapping_rules"),
      // Data transformation rules
      status: actionStatusEnum("status").default("pending"),
      lastTriggered: timestamp2("last_triggered"),
      successCount: integer2("success_count").default(0),
      failureCount: integer2("failure_count").default(0),
      isActive: boolean("is_active").default(true),
      createdBy: varchar("created_by").references(() => users.id).notNull(),
      createdAt: timestamp2("created_at").defaultNow().notNull(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
    intuitionRecords = pgTable2("intuition_records", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      executiveId: varchar("executive_id").references(() => users.id).notNull(),
      title: varchar("title", { length: 255 }).notNull(),
      description: text2("description").notNull(),
      // The original hunch/intuition
      confidenceLevel: confidenceEnum("confidence_level").default("medium"),
      timeframe: varchar("timeframe", { length: 100 }),
      // When they expect this to materialize
      relatedDomain: varchar("related_domain", { length: 100 }),
      // market, technology, regulation, etc.
      aiValidationStatus: varchar("ai_validation_status", { length: 50 }).default("pending"),
      aiFindings: text2("ai_findings"),
      // AI's analysis of the intuition
      supportingData: jsonb("supporting_data"),
      // Data points found by AI
      contradictingData: jsonb("contradicting_data"),
      // Data that challenges the hunch
      validationScore: decimal("validation_score", { precision: 3, scale: 2 }),
      // AI confidence in intuition
      outcome: varchar("outcome", { length: 100 }),
      // Track if the intuition was correct
      followUpActions: jsonb("follow_up_actions"),
      // Actions taken based on this insight
      isValidated: boolean("is_validated"),
      validatedAt: timestamp2("validated_at"),
      createdAt: timestamp2("created_at").defaultNow().notNull(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
    syntheticScenarios = pgTable2("synthetic_scenarios", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      title: varchar("title", { length: 255 }).notNull(),
      description: text2("description").notNull(),
      category: varchar("category", { length: 100 }).notNull(),
      // black_swan, market_shift, tech_disruption
      likelihood: decimal("likelihood", { precision: 3, scale: 2 }),
      potentialImpact: riskLevelEnum("potential_impact"),
      timeHorizon: varchar("time_horizon", { length: 50 }),
      // 6m, 12m, 18m, 24m+
      triggerSigns: jsonb("trigger_signs"),
      // Early warning indicators
      contextData: jsonb("context_data"),
      // AI reasoning and data sources
      responseFramework: jsonb("response_framework"),
      // Recommended decision framework
      keyStakeholders: jsonb("key_stakeholders"),
      // Who should be involved
      strategicImplications: text2("strategic_implications"),
      generatedBy: varchar("generated_by").default("ai"),
      // ai, human, hybrid
      parentQuery: text2("parent_query"),
      // Original executive question that spawned this
      upvotes: integer2("upvotes").default(0),
      // C-suite validation
      status: varchar("status", { length: 50 }).default("draft"),
      implementedAsScenario: uuid("implemented_as_scenario").references(() => strategicScenarios.id),
      createdAt: timestamp2("created_at").defaultNow().notNull(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
