      // "reorder_decision_tree", "add_stakeholder", "update_template", "adjust_budget", "add_trigger"
      suggestionTitle: varchar("suggestion_title", { length: 255 }).notNull(),
      suggestionDescription: text2("suggestion_description").notNull(),
      // Current vs Recommended
      currentValue: jsonb("current_value"),
      // What exists now
      recommendedValue: jsonb("recommended_value"),
