    executionValidationReports = pgTable2("execution_validation_reports", {
      id: uuid("id").primaryKey().defaultRandom(),
      scenarioId: uuid("scenario_id").references(() => strategicScenarios.id).notNull(),
      executionId: uuid("execution_id").notNull(),
      // Unique identifier for this specific execution
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      executedBy: varchar("executed_by").references(() => users.id).notNull(),
      executionDate: timestamp2("execution_date").notNull(),
      validationDate: timestamp2("validation_date").defaultNow(),
      // Date report was generated (48hrs after execution)
      // Predicted vs Actual Comparisons
      predictedExecutionTime: integer2("predicted_execution_time"),
      // Minutes
      actualExecutionTime: integer2("actual_execution_time"),
      // Minutes
      timeSavingsRealized: integer2("time_savings_realized"),
      // Minutes saved vs traditional approach
      predictedOutcomes: jsonb("predicted_outcomes").notNull(),
      // Expected results from playbook
      actualOutcomes: jsonb("actual_outcomes").notNull(),
      // Actual results achieved
      outcomeAccuracy: decimal("outcome_accuracy", { precision: 3, scale: 2 }),
      // 0.00-1.00 prediction accuracy
      predictedCost: decimal("predicted_cost", { precision: 12, scale: 2 }),
      actualCost: decimal("actual_cost", { precision: 12, scale: 2 }),
      predictedRisks: jsonb("predicted_risks"),
      // Risks identified before execution
      actualRisks: jsonb("actual_risks"),
      // Risks that materialized during execution
      riskPredictionAccuracy: decimal("risk_prediction_accuracy", { precision: 3, scale: 2 }),
      // Success Metrics
      overallSuccessRating: integer2("overall_success_rating").notNull(),
      // 1-10 rating
      kpiTargetsHit: integer2("kpi_targets_hit"),
      // Number of KPI targets achieved
      kpiTargetsTotal: integer2("kpi_targets_total"),
      // Total number of KPI targets
      // Learnings and Improvements
      whatWorked: jsonb("what_worked"),
      // Array of successful strategies
      whatFailed: jsonb("what_failed"),
      // Array of unsuccessful strategies
      unexpectedChallenges: jsonb("unexpected_challenges"),
      // Surprises encountered
      playbookImprovements: jsonb("playbook_improvements"),
      // Recommended changes to playbook
      institutionalLearnings: text2("institutional_learnings"),
      // Key takeaways for future executions
      // ROI Calculation
      estimatedRoi: decimal("estimated_roi", { precision: 12, scale: 2 }),
      // Return on investment
      timeSavedHours: decimal("time_saved_hours", { precision: 8, scale: 2 }),
      costSavedUsd: decimal("cost_saved_usd", { precision: 12, scale: 2 }),
      // Stakeholder Feedback
      stakeholderFeedback: jsonb("stakeholder_feedback"),
      // Feedback from involved stakeholders
      executiveSummary: text2("executive_summary"),
      // High-level summary for board
      // Confidence for Future Use
      recommendForFutureUse: boolean("recommend_for_future_use").default(true),
      confidenceAdjustment: integer2("confidence_adjustment"),
      // +/- adjustment to future confidence scores
      createdAt: timestamp2("created_at").defaultNow(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
