      async getExecutionStatus(instanceId) {
        const instance = await this.getExecutionInstanceById(instanceId);
        if (!instance) return null;
        const tasks4 = await this.getExecutionInstanceTasks(instanceId);
        const taskUserIds = tasks4.filter((t) => t.assignedUserId).map((t) => t.assignedUserId);
        const notifs = taskUserIds.length > 0 ? await db.select().from(notifications).where(
          and(
            eq(notifications.entityId, instanceId),
            inArray(notifications.userId, taskUserIds)
          )
        ) : [];
        const acknowledgedCount = notifs.filter((n) => n.readAt).length;
        const totalStakeholders = new Set(taskUserIds).size;
        const coordinationComplete = totalStakeholders > 0 ? acknowledgedCount / totalStakeholders >= 0.8 : false;
        const elapsedMinutes = instance.startedAt ? Math.floor((Date.now() - new Date(instance.startedAt).getTime()) / 6e4) : 0;
        return {
          executionInstance: instance,
          tasks: tasks4,
          notifications: notifs,
          coordination: {
            startTime: instance.startedAt,
            elapsedMinutes,
            tasksDistributed: tasks4.length,
            notificationsSent: notifs.length,
            acknowledged: acknowledgedCount,
            coordinationComplete
          }
        };
      }
