// server/services/integrations/adapters/JiraAdapter.ts
var JiraAdapter = class {
  vendor = "jira";
  async createTask(payload, config) {
    const cloudId = config.config.cloudId;
    if (!cloudId) {
      return { provider: "jira", action: "create-task", success: false, error: "No cloud ID" };
    }
    try {
      let projectKey = config.config.projectKey;
      if (!projectKey) {
        const projRes = await fetch(
          `https://api.atlassian.com/ex/jira/${cloudId}/rest/api/3/project/search?maxResults=5`,
          { headers: { Authorization: `Bearer ${config.accessToken}`, Accept: "application/json" } }
        );
        if (projRes.ok) {
          const projData = await projRes.json();
          const projects2 = projData.values || [];
          projectKey = projects2[0]?.key;
        }
      }
      if (!projectKey) {
        return { provider: "jira", action: "create-task", success: false, error: "No projects available" };
      }
      const issueData = {
        fields: {
          project: { key: projectKey },
          summary: `[Execution OS] ${payload.title}`,
          issuetype: { name: "Task" },
          description: {
            type: "doc",
            version: 1,
            content: [{
              type: "paragraph",
              content: [{ type: "text", text: payload.description }]
            }]
          }
        }
      };
      const issueRes = await fetch(
        `https://api.atlassian.com/ex/jira/${cloudId}/rest/api/3/issue`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${config.accessToken}`,
            "Content-Type": "application/json",
            Accept: "application/json"
          },
          body: JSON.stringify(issueData)
        }
      );
      if (issueRes.ok) {
        const issue = await issueRes.json();
        return {
          provider: "jira",
          action: "create-issue",
          success: true,
          detail: {
            key: issue.key,
            id: issue.id,
            url: `${config.config.cloudUrl || ""}/browse/${issue.key}`,
            taskName: payload.title
          }
        };
      } else {
        const err = await issueRes.text();
        return {
          provider: "jira",
          action: "create-issue",
          success: false,
          error: `HTTP ${issueRes.status}: ${err.slice(0, 200)}`,
          detail: { taskName: payload.title }
        };
      }
    } catch (err) {
      return {
        provider: "jira",
        action: "create-issue",
        success: false,
        error: err instanceof Error ? err.message : "Unknown error",
        detail: { taskName: payload.title }
      };
    }
  }
  async sendNotification(payload, config) {
    return { provider: "jira", action: "send-notification", success: true, detail: "Not implemented for Jira" };
  }
  async testConnection(config) {
    const cloudId = config.config.cloudId;
    if (!cloudId) return false;
    try {
      const response = await fetch(`https://api.atlassian.com/ex/jira/${cloudId}/rest/api/3/myself`, {
        headers: {
          "Authorization": `Bearer ${config.accessToken}`,
          "Content-Type": "application/json"
        }
      });
      return response.ok;
    } catch {
      return false;
    }
  }
};

// server/services/integrations/adapters/SlackAdapter.ts
var SlackAdapter = class {
  vendor = "slack";
  async createTask(payload, config) {
    return this.sendNotification({
      title: `Task: ${payload.title}`,
      message: payload.description,
      severity: "info"
    }, config);
  }
  async sendNotification(payload, config) {
    try {
      let channelId = config.config.channelId;
      if (!channelId) {
        const chanRes = await fetch(
          "https://slack.com/api/conversations.list?types=public_channel&limit=100",
          { headers: { Authorization: `Bearer ${config.accessToken}` } }
        );
        const chanData = await chanRes.json();
        if (chanData.ok) {
          const channels = chanData.channels || [];
          const preferred = channels.find(
            (c) => c.name === "general" || c.name === "execution-os" || c.name === "strategy" || c.name === "operations"
          );
          channelId = preferred?.id || channels[0]?.id;
        }
      }
      if (!channelId) {
        return { provider: "slack", action: "send-notification", success: false, error: "No channels available" };
      }
      const response = await fetch("https://slack.com/api/chat.postMessage", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${config.accessToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          channel: channelId,
          text: payload.title,
          blocks: payload.blocks || [
            {
              type: "header",
              text: { type: "plain_text", text: payload.title, emoji: true }
            },
            {
              type: "section",
              text: {
                type: "mrkdwn",
                text: payload.message
              }
            }
          ]
        })
      });
      const data = await response.json();
      if (data.ok) {
        return {
          provider: "slack",
          action: "send-notification",
          success: true,
          detail: { channel: data.channel, ts: data.ts }
        };
      } else {
        return {
          provider: "slack",
          action: "send-notification",
          success: false,
          error: data.error
        };
      }
    } catch (err) {
      return {
        provider: "slack",
        action: "send-notification",
        success: false,
        error: err instanceof Error ? err.message : "Unknown error"
      };
    }
  }
  async testConnection(config) {
    try {
      const response = await fetch("https://slack.com/api/auth.test", {
        headers: {
          "Authorization": `Bearer ${config.accessToken}`
        }
      });
      const data = await response.json();
      return data.ok === true;
    } catch {
      return false;
    }
  }
};

