// server/replit_integrations/chat/storage.ts
init_db();
init_schema();
import { eq as eq14, desc as desc9 } from "drizzle-orm";
var chatStorage = {
  async getConversation(id) {
    const [conversation] = await db.select().from(conversations).where(eq14(conversations.id, id));
    return conversation;
  },
  async getAllConversations() {
    return db.select().from(conversations).orderBy(desc9(conversations.createdAt));
  },
  async createConversation(title) {
    const [conversation] = await db.insert(conversations).values({ title }).returning();
    return conversation;
  },
  async deleteConversation(id) {
    await db.delete(messages).where(eq14(messages.conversationId, id));
    await db.delete(conversations).where(eq14(conversations.id, id));
  },
  async getMessagesByConversation(conversationId) {
    return db.select().from(messages).where(eq14(messages.conversationId, conversationId)).orderBy(messages.createdAt);
  },
  async createMessage(conversationId, role, content) {
    const [message] = await db.insert(messages).values({ conversationId, role, content }).returning();
    return message;
  }
};

// server/replit_integrations/audio/client.ts
import OpenAI4, { toFile } from "openai";
var openai3 = new OpenAI4({
  apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
  baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL
});
async function textToSpeechStream(text3, voice = "alloy") {
  const stream = await openai3.chat.completions.create({
    model: "gpt-audio-mini",
    modalities: ["text", "audio"],
    audio: { voice, format: "pcm16" },
    messages: [
      { role: "system", content: "You are an assistant that performs text-to-speech." },
      { role: "user", content: `Repeat the following text verbatim: ${text3}` }
    ],
    stream: true
  });
  return async function* () {
    for await (const chunk of stream) {
      const delta = chunk.choices?.[0]?.delta;
      if (!delta) continue;
      if (delta?.audio?.data) {
        yield delta.audio.data;
      }
    }
  }();
}
async function speechToText(audioBuffer, format = "wav") {
  const file = await toFile(audioBuffer, `audio.${format}`);
  const response = await openai3.audio.transcriptions.create({
    file,
    model: "gpt-4o-mini-transcribe"
  });
  return response.text;
}
var SentenceParser = class {
  buffer = "";
  seq = 0;
  segmenter;
  constructor(locale = "en") {
    this.segmenter = new Intl.Segmenter(locale, { granularity: "sentence" });
  }
  /**
   * Feed tokens from LLM stream.
   * Returns complete sentences with sequence numbers.
   */
  feed(token) {
    this.buffer += token;
    const sentences = [];
    const segments = Array.from(this.segmenter.segment(this.buffer));
    for (let i = 0; i < segments.length - 1; i++) {
      const text3 = segments[i].segment.trim();
      if (text3) {
        sentences.push({ seq: this.seq++, text: text3 });
      }
    }
    if (segments.length > 0) {
      this.buffer = segments[segments.length - 1].segment;
    }
    return sentences;
  }
  /** Flush any remaining text as final sentence */
  flush() {
    const text3 = this.buffer.trim();
    this.buffer = "";
    return text3 ? { seq: this.seq++, text: text3 } : null;
  }
  reset() {
    this.buffer = "";
    this.seq = 0;
  }
};
async function* voiceChatWithTextModel(audioBuffer, options2 = {}) {
  const {
    voice = "alloy",
    inputFormat = "wav",
    systemPrompt = "You are a helpful assistant.",
    chatHistory = [],
    textModel = "gpt-5",
    // the newest OpenAI model is "gpt-5" which was released August 7, 2025
    locale = "en"
  } = options2;
  const userText = await speechToText(audioBuffer, inputFormat);
  yield { type: "user_transcript", data: userText };
  const messages2 = [
    { role: "system", content: systemPrompt },
    ...chatHistory,
    { role: "user", content: userText }
  ];
  const textStream = await openai3.chat.completions.create({
    model: textModel,
    messages: messages2,
    stream: true
  });
  const parser = new SentenceParser(locale);
  const activeStreams = [];
  let nextSeqToYield = 0;
  let fullTranscript = "";
  const startTTS = async (sentence) => {
    const stream = await textToSpeechStream(sentence.text, voice);
    activeStreams.push({
      seq: sentence.seq,
      iterator: stream[Symbol.asyncIterator](),
      done: false
    });
  };
  async function* drainAudioInOrder() {
    while (activeStreams.length > 0) {
      const currentStream = activeStreams.find((s) => s.seq === nextSeqToYield);
      if (!currentStream) {
        return;
      }
      if (currentStream.done) {
        activeStreams.splice(activeStreams.indexOf(currentStream), 1);
        nextSeqToYield++;
        continue;
      }
      const { value, done } = await currentStream.iterator.next();
      if (done) {
        currentStream.done = true;
        activeStreams.splice(activeStreams.indexOf(currentStream), 1);
        nextSeqToYield++;
      } else {
        yield { type: "audio", seq: currentStream.seq, data: value };
      }
    }
  }
  for await (const chunk of textStream) {
    const token = chunk.choices[0]?.delta?.content || "";
    if (!token) continue;
    fullTranscript += token;
    const sentences = parser.feed(token);
    for (const sentence of sentences) {
      yield { type: "sentence", seq: sentence.seq, text: sentence.text };
      await startTTS(sentence);
    }
    for await (const event of drainAudioInOrder()) {
      yield event;
    }
  }
  const finalSentence = parser.flush();
  if (finalSentence) {
    yield { type: "sentence", seq: finalSentence.seq, text: finalSentence.text };
    await startTTS(finalSentence);
  }
  while (activeStreams.length > 0) {
    for await (const event of drainAudioInOrder()) {
      yield event;
    }
    if (activeStreams.length > 0 && !activeStreams.find((s) => s.seq === nextSeqToYield)) {
      await new Promise((r) => setTimeout(r, 10));
    }
  }
  yield { type: "transcript", data: fullTranscript };
  yield { type: "done" };
}

// server/replit_integrations/audio/routes.ts
function registerAudioRoutes(app2) {
  app2.post("/api/tts", async (req, res) => {
    try {
      const {
        text: text3,
        voice = "onyx"
      } = req.body;
      if (!text3) {
        return res.status(400).json({ error: "Text is required" });
      }
      const response = await openai3.audio.speech.create({
        model: "tts-1",
        voice,
        input: text3,
        response_format: "mp3"
      });
      const arrayBuffer = await response.arrayBuffer();
      const audioBuffer = Buffer.from(arrayBuffer);
      const base64Audio = audioBuffer.toString("base64");
      res.json({
        audio: base64Audio,
        format: "mp3",
        voice
      });
    } catch (error) {
      console.error("Error generating speech:", error);
      res.status(500).json({ error: "Failed to generate speech" });
    }
  });
  app2.get("/api/conversations", async (req, res) => {
    try {
      const conversations2 = await chatStorage.getAllConversations();
      res.json(conversations2);
    } catch (error) {
      console.error("Error fetching conversations:", error);
      res.status(500).json({ error: "Failed to fetch conversations" });
    }
  });
  app2.get("/api/conversations/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const conversation = await chatStorage.getConversation(id);
      if (!conversation) {
        return res.status(404).json({ error: "Conversation not found" });
      }
      const messages2 = await chatStorage.getMessagesByConversation(id);
      res.json({ ...conversation, messages: messages2 });
    } catch (error) {
      console.error("Error fetching conversation:", error);
      res.status(500).json({ error: "Failed to fetch conversation" });
    }
  });
  app2.post("/api/conversations", async (req, res) => {
    try {
      const { title } = req.body;
      const conversation = await chatStorage.createConversation(title || "New Chat");
      res.status(201).json(conversation);
    } catch (error) {
      console.error("Error creating conversation:", error);
      res.status(500).json({ error: "Failed to create conversation" });
    }
  });
  app2.delete("/api/conversations/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      await chatStorage.deleteConversation(id);
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting conversation:", error);
      res.status(500).json({ error: "Failed to delete conversation" });
    }
  });
  app2.post("/api/conversations/:id/messages", async (req, res) => {
    try {
      const conversationId = parseInt(req.params.id);
      const { audio, voice = "alloy", inputFormat = "wav" } = req.body;
      if (!audio) {
        return res.status(400).json({ error: "Audio data (base64) is required" });
      }
      const audioBuffer = Buffer.from(audio, "base64");
      const userTranscript = await speechToText(audioBuffer, inputFormat);
      await chatStorage.createMessage(conversationId, "user", userTranscript);
      const existingMessages = await chatStorage.getMessagesByConversation(conversationId);
      const chatHistory = existingMessages.map((m) => ({
        role: m.role,
        content: m.content
      }));
      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");
      res.write(`data: ${JSON.stringify({ type: "user_transcript", data: userTranscript })}

`);
      const stream = await openai3.chat.completions.create({
        model: "gpt-audio-mini",
        modalities: ["text", "audio"],
        audio: { voice, format: "pcm16" },
        messages: chatHistory,
        stream: true
      });
      let assistantTranscript = "";
      for await (const chunk of stream) {
        const delta = chunk.choices?.[0]?.delta;
        if (!delta) continue;
        if (delta?.audio?.transcript) {
          assistantTranscript += delta.audio.transcript;
          res.write(`data: ${JSON.stringify({ type: "transcript", data: delta.audio.transcript })}

`);
        }
        if (delta?.audio?.data) {
          res.write(`data: ${JSON.stringify({ type: "audio", data: delta.audio.data })}

`);
        }
      }
      await chatStorage.createMessage(conversationId, "assistant", assistantTranscript);
      res.write(`data: ${JSON.stringify({ type: "done", transcript: assistantTranscript })}

`);
      res.end();
    } catch (error) {
      console.error("Error processing voice message:", error);
      if (res.headersSent) {
        res.write(`data: ${JSON.stringify({ type: "error", error: "Failed to process voice message" })}

`);
        res.end();
      } else {
        res.status(500).json({ error: "Failed to process voice message" });
      }
    }
  });
  app2.post("/api/conversations/:id/voice-stream", async (req, res) => {
    try {
      const conversationId = parseInt(req.params.id);
      const { audio, voice = "alloy", inputFormat = "wav", locale = "en" } = req.body;
      if (!audio) {
        return res.status(400).json({ error: "Audio data (base64) is required" });
      }
      const existingMessages = await chatStorage.getMessagesByConversation(conversationId);
      const chatHistory = existingMessages.map((m) => ({
        role: m.role,
        content: m.content
      }));
      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");
      const audioBuffer = Buffer.from(audio, "base64");
      let userTranscript = "";
      let assistantTranscript = "";
      for await (const event of voiceChatWithTextModel(audioBuffer, {
        voice,
        inputFormat,
        chatHistory,
        locale
      })) {
        if (event.type === "user_transcript") {
          userTranscript = event.data || "";
          await chatStorage.createMessage(conversationId, "user", userTranscript);
        }
        if (event.type === "transcript") {
          assistantTranscript = event.data || "";
        }
        res.write(`data: ${JSON.stringify(event)}

`);
      }
      await chatStorage.createMessage(conversationId, "assistant", assistantTranscript);
      res.end();
    } catch (error) {
      console.error("Error in voice stream:", error);
      if (res.headersSent) {
        res.write(`data: ${JSON.stringify({ type: "error", error: "Voice stream failed" })}

`);
        res.end();
      } else {
        res.status(500).json({ error: "Voice stream failed" });
      }
    }
  });
}

